// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { evolvePath, getLength, getPointAtLength } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — guarantees readiness before frame 0
const { fontFamily: interFamily } = loadInter();



export type PropertyGraphProps = Record<string, any>;

const PropertyGraph: React.FC<PropertyGraphProps> = ({
  backgroundColor = "#020617",
  transparentBackground = false,
  durationInSeconds = 8,
  title = "1-Year Property Value Growth",
  startValue = 750000,
  endValue = 900000,
  startLabel = "Jan",
  endLabel = "Dec",
  emoji = "🏠",
  lineColor = "#4ade80",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Timings & Animations
  // Title fades and slides in
  const titleOpacity = interpolate(frame, [10, 25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [10, 25], [-20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.ease),
  });

  // Grid lines reveal
  const gridLineProgress = interpolate(frame, [15, 30], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.ease),
  });

  // Graph line draws over 3 seconds
  const drawProgress = interpolate(frame, [30, 120], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.ease),
  });

  // Emoji and tooltip pop in slightly before the line starts drawing
  const emojiScale = spring({
    frame: frame - 20,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  // Canvas bounds for the graph
  const startX = width * 0.15;
  const endX = width * 0.85;
  const graphBottom = height * 0.75;
  const graphTop = height * 0.35;
  const graphHeight = graphBottom - graphTop;

  // Dynamic Y-axis scale logic based on exact input values
  let minVal = Math.min(startValue, endValue);
  let maxVal = Math.max(startValue, endValue);
  
  // Handle edge case where values are identical
  if (minVal === maxVal) {
    if (minVal === 0) {
      maxVal = 100;
    } else {
      minVal = minVal * 0.8;
      maxVal = maxVal * 1.2;
    }
  }

  // Add 15% padding so line doesn't hit the absolute top/bottom boundaries
  const padding = (maxVal - minVal) * 0.15;
  minVal -= padding;
  maxVal += padding;

  // Map arbitrary values to physical Y coordinates
  const mapValueToY = (val: number) => {
    const ratio = (val - minVal) / (maxVal - minVal);
    return graphBottom - ratio * graphHeight;
  };

  const startY = mapValueToY(startValue);
  const endY = mapValueToY(endValue);

  // Cubic bezier for a smooth, aesthetic S-curve
  const cp1X = startX + (endX - startX) * 0.4;
  const cp1Y = startY;
  const cp2X = startX + (endX - startX) * 0.6;
  const cp2Y = endY;

  // Construct standard SVG path
  const d = `M ${startX} ${startY} C ${cp1X} ${cp1Y} ${cp2X} ${cp2Y} ${endX} ${endY}`;

  // Process the path mathematically
  const pathLength = getLength(d);
  const safeLength = Math.max(0, Math.min(pathLength, pathLength * drawProgress));
  const evolution = evolvePath(drawProgress, d);
  
  // Safe point extraction to prevent any parser crashes at exact 0 or over-length
  let point = { x: startX, y: startY };
  try {
    point = getPointAtLength(d, safeLength);
  } catch (e) {
    point = { x: startX, y: startY };
  }

  // Active Tooltip Value Calculation
  const currentValue = interpolate(drawProgress, [0, 1], [startValue, endValue]);
  const formattedValue = new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  }).format(Math.round(currentValue));

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      {/* Title */}
      <h1
        style={{
          position: "absolute",
          top: height * 0.15,
          left: width * 0.1,
          right: width * 0.1,
          textAlign: "center",
          color: "white",
          fontSize: 56,
          fontWeight: 800,
          letterSpacing: "-0.02em",
          opacity: titleOpacity,
          transform: `translateY(${titleY}px)`,
          margin: 0,
        }}
      >
        {title}
      </h1>

      {/* Grid and Axes (SVG Layer) */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0, overflow: "visible" }}
      >
        {/* Horizontal Grid Lines mapped visually onto the scale */}
        {[0, 0.5, 1].map((ratio, i) => {
          const y = graphBottom - ratio * graphHeight;
          return (
            <line
              key={i}
              x1={startX}
              y1={y}
              x2={startX + (endX - startX) * gridLineProgress}
              y2={y}
              stroke="#ffffff15"
              strokeWidth={2}
            />
          );
        })}

        {/* X-Axis Main Base Line */}
        <line
          x1={startX}
          y1={graphBottom}
          x2={startX + (endX - startX) * gridLineProgress}
          y2={graphBottom}
          stroke="#ffffff44"
          strokeWidth={4}
          strokeLinecap="round"
        />

        {/* Y-Axis Line */}
        <line
          x1={startX}
          y1={graphBottom}
          x2={startX}
          y2={graphBottom - graphHeight * gridLineProgress}
          stroke="#ffffff44"
          strokeWidth={4}
          strokeLinecap="round"
        />

        {/* The Animated Data Line */}
        <path
          d={d}
          stroke={lineColor}
          strokeWidth={8}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={evolution.strokeDasharray}
          strokeDashoffset={evolution.strokeDashoffset}
          style={{ filter: `drop-shadow(0 0 16px ${lineColor}88)` }}
        />
      </svg>

      {/* Y-Axis Text Labels */}
      {[0, 0.5, 1].map((ratio, i) => {
        const y = graphBottom - ratio * graphHeight;
        const val = minVal + ratio * (maxVal - minVal);
        const formattedY = new Intl.NumberFormat("en-US", {
          style: "currency",
          currency: "USD",
          maximumSignificantDigits: 3,
          notation: "compact",
        }).format(val);

        return (
          <div
            key={`y-label-${i}`}
            style={{
              position: "absolute",
              right: width - startX + 24,
              top: y,
              transform: "translateY(-50%)",
              color: "#94a3b8",
              fontSize: 24,
              fontWeight: 500,
              opacity: gridLineProgress,
            }}
          >
            {formattedY}
          </div>
        );
      })}

      {/* X-Axis Text Labels */}
      <div
        style={{
          position: "absolute",
          left: startX,
          top: graphBottom + 24,
          transform: "translateX(-50%)",
          color: "#94a3b8",
          fontSize: 28,
          fontWeight: 600,
          opacity: gridLineProgress,
        }}
      >
        {startLabel}
      </div>
      <div
        style={{
          position: "absolute",
          left: endX,
          top: graphBottom + 24,
          transform: "translateX(-50%)",
          color: "#94a3b8",
          fontSize: 28,
          fontWeight: 600,
          opacity: gridLineProgress,
        }}
      >
        {endLabel}
      </div>

      {/* Active Point Tracker (Container moves, children scale relatively) */}
      <div
        style={{
          position: "absolute",
          left: point.x,
          top: point.y,
          zIndex: 10,
        }}
      >
        {/* Dynamic Tooltip */}
        <div
          style={{
            position: "absolute",
            bottom: 45, // Safely clears the emoji boundaries
            left: "50%",
            transform: `translateX(-50%) scale(${emojiScale})`,
            transformOrigin: "bottom center",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
          }}
        >
          <div
            style={{
              backgroundColor: "#0f172a",
              border: `2px solid ${lineColor}`,
              color: "white",
              fontSize: 28,
              fontWeight: 700,
              padding: "10px 20px",
              borderRadius: 16,
              whiteSpace: "nowrap",
              boxShadow: `0 8px 24px rgba(0,0,0,0.5), 0 0 12px ${lineColor}40`,
            }}
          >
            {formattedValue}
          </div>
          {/* Tooltip Arrow */}
          <div
            style={{
              width: 0,
              height: 0,
              borderLeft: "12px solid transparent",
              borderRight: "12px solid transparent",
              borderTop: `12px solid ${lineColor}`,
              marginTop: "-2px",
            }}
          />
        </div>

        {/* The Tracking Emoji */}
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            transform: `translate(-50%, -50%) scale(${emojiScale})`,
            fontSize: 64,
            filter: "drop-shadow(0px 8px 16px rgba(0,0,0,0.5))",
          }}
        >
          {emoji}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PropertyGraph;